const MODEL_ALIASES = {
  "ATEM SDI Extreme SDI": 23,
  "ATEM Constellation 8K": 11,
  "Constellation 8K": 11,
  "ATEM Constellation 8K (HD/4K Mode)": 11,
  "ATEM 1 M/E Constellation": 18,
  "ATEM 2 M/E Constellation": 19,
  "ATEM 4 M/E Constellation": 20
};

/**
 * Robust Model Resolver:
 * Finds model capabilities by exact XML product name, Companion label, or known alias.
 * @param {string} name - Product or model name from XML <Profile product="..."> or UI selection
 * @returns {object} Model capability descriptor
 */
function findModelCapabilities(name) {
  if (!name || typeof name !== 'string') return MODEL_CAPABILITIES["Unknown / Custom ATEM"];
  const trimmed = name.trim();

  // 1. Direct match in MODEL_CAPABILITIES (Companion label)
  if (MODEL_CAPABILITIES[trimmed]) return MODEL_CAPABILITIES[trimmed];

  // 2. Direct match in MODEL_ALIASES
  if (MODEL_ALIASES[trimmed]) {
    const aliasId = MODEL_ALIASES[trimmed];
    const found = Object.values(MODEL_CAPABILITIES).find(m => m.id === aliasId);
    if (found) return found;
  }

  // 3. Match against xmlProductName
  const byXmlName = Object.values(MODEL_CAPABILITIES).find(
    m => m.xmlProductName && m.xmlProductName.toLowerCase() === trimmed.toLowerCase()
  );
  if (byXmlName) return byXmlName;

  // 4. Try stripping "ATEM " prefix
  const stripped = trimmed.replace(/^ATEM\s+/i, '');
  if (MODEL_CAPABILITIES[stripped]) return MODEL_CAPABILITIES[stripped];

  // 5. Loose match (normalized lowercase without punctuation)
  const norm = trimmed.toLowerCase().replace(/[^a-z0-9]/g, '');
  const byLoose = Object.values(MODEL_CAPABILITIES).find(m => {
    const lNorm = (m.label || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const xNorm = (m.xmlProductName || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    return lNorm === norm || xNorm === norm || norm.includes(lNorm) || norm.includes(xNorm);
  });
  if (byLoose) return byLoose;

  // Fallback
  return MODEL_CAPABILITIES["Unknown / Custom ATEM"];
}
